const CATALOGO_MAGICOS = [{"id":"magico.adaga-venenosa","nome":"Adaga Venenosa","tipo":"Arma","rar":"Raro","sint":"","desc":"Adaga +1. Uma vez por dia, com uma ação bônus, a lâmina se cobre de veneno: o próximo alvo atingido faz teste de Constituição CD 15 ou sofre 2d10 de veneno e fica envenenado por 1 minuto."},
{"id":"magico.arco-de-energia","nome":"Arco de Energia","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Arco +1 sem corda. Cada vez que você puxa o braço, surge uma flecha de energia dourada que causa dano de energia. Também dá pra disparar uma flecha que vira uma corda ou uma ponte de energia."},
{"id":"magico.arco-do-juramento","nome":"Arco do Juramento","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Quando você dispara dizendo o juramento, o alvo vira seu inimigo jurado por 7 dias: você tem vantagem contra ele, ignora cobertura e causa +3d6 perfurante. Enquanto ele viver, você tem desvantagem com outras armas."},
{"id":"magico.arma-1-2-ou-3","nome":"Arma +1, +2 ou +3","tipo":"Arma","rar":"Varia","sint":"","desc":"Qualquer arma encantada com +1 (incomum), +2 (rara) ou +3 (muito rara) no ataque e no dano."},
{"id":"magico.arma-cruel","nome":"Arma Cruel","tipo":"Arma","rar":"Raro","sint":"","desc":"Qualquer arma que causa +2d6 de dano do mesmo tipo dela em toda criatura que acertar."},
{"id":"magico.arma-do-alerta","nome":"Arma do Alerta","tipo":"Arma","rar":"Incomum","sint":"Sim","desc":"Enquanto estiver perto de você, você e os aliados a até 9 m acordam no início de um combate, têm vantagem em iniciativa e não podem ser pegos de surpresa."},
{"id":"magico.azagaia-do-relampago","nome":"Azagaia do Relâmpago","tipo":"Arma","rar":"Incomum","sint":"","desc":"Azagaia que pode causar dano de raio. Uma vez por dia, arremessada, vira um relâmpago numa linha até o alvo: quem estiver no caminho sofre 4d6 de raio (teste de Destreza), e o alvo leva ainda mais."},
{"id":"magico.bordao-do-acrobata","nome":"Bordão do Acrobata","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Bordão +2 que brilha em verde quando você quiser. Com uma ação bônus, vira uma vara de até 3 m (pra saltar, dar ataques com alcance) ou se encolhe numa varinha de 30 cm. Também ajuda a desviar de ataques à distância."},
{"id":"magico.cimitarra-da-velocidade","nome":"Cimitarra da Velocidade","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Cimitarra +2 que deixa você fazer um ataque extra com ela como ação bônus em todo turno."},
{"id":"magico.clava-grande-trovejante","nome":"Clava Grande Trovejante","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Sintonizado, sua Força vira 20. Cada acerto causa +1d8 de trovão (+3d8 em objetos), e uma vez por dia você bate no chão causando um terremoto."},
{"id":"magico.defensora","nome":"Defensora","tipo":"Arma","rar":"Lendário","sint":"Sim","desc":"Arma +3. No primeiro ataque de cada turno, você pode passar parte do bônus da arma pra sua CA, como +1 na arma e +2 na CA. Perfeita pra quem quer ser ofensivo e defensivo ao mesmo tempo."},
{"id":"magico.espada-vorpal","nome":"Espada Vorpal","tipo":"Arma","rar":"Lendário","sint":"Sim","desc":"Espada +3 que ignora resistência a cortante. Num 20 natural, corta a cabeça do alvo e mata na hora (se ele tiver cabeça e precisar dela); se não der, causa +30 de dano cortante."},
{"id":"magico.ladra-das-nove-vidas","nome":"Ladra das Nove Vidas","tipo":"Arma","rar":"Muito raro","sint":"Sim","desc":"Arma +2 com algumas cargas. Num 20 natural contra uma criatura com menos de 100 PV, ela faz teste de Constituição CD 15 ou morre na hora, e a arma gasta uma carga. Quando as cargas acabam, vira uma arma +2 comum."},
{"id":"magico.lamina-solar","nome":"Lâmina Solar","tipo":"Arma","rar":"Raro","sint":"Sim","desc":"Parece só um cabo de espada. Com uma ação bônus, surge uma lâmina de luz pura: espada longa +2 com acuidade que causa dano radiante, +1d8 contra mortos-vivos, e ilumina como o sol."},
{"id":"magico.lingua-de-fogo","nome":"Língua de Fogo","tipo":"Arma","rar":"Raro","sint":"Sim","desc":"Arma que pega fogo com uma palavra de comando (ação bônus): ilumina 12 m e causa +2d6 de fogo a cada acerto. Uma das armas mágicas mais icônicas."},
{"id":"magico.machado-do-berserker","nome":"Machado do Berserker","tipo":"Arma","rar":"Raro","sint":"Sim","desc":"Machado +1 que também aumenta seu PV máximo em 1 por nível. Mas é amaldiçoado: você não quer se separar dele, tem desvantagem com outras armas, e sempre que leva dano em combate pode entrar em fúria e atacar a criatura mais próxima, amigo ou inimigo."},
{"id":"magico.martelo-arremessador-anao","nome":"Martelo Arremessador Anão","tipo":"Arma","rar":"Muito raro","sint":"Sim (só anão ou quem usa o Cinto dos Anões)","desc":"Martelo de guerra +3 que pode ser arremessado (6/18 m) e volta pra sua mão. Arremessado, causa +1d8 de energia, ou +2d8 contra gigantes. Só se sintoniza com anões ou quem usa um Cinto dos Anões."},
{"id":"magico.martelo-dos-trovoes","nome":"Martelo dos Trovões","tipo":"Arma","rar":"Lendário","sint":"Sim","desc":"Martelo +1 com 5 cargas. Gastando uma, você arremessa o martelo (6/18 m) e ele explode em trovão quando acerta, atordoando quem estiver perto. Com um cinto de força de gigante e manoplas de ogro, fica ainda mais forte contra gigantes."},
{"id":"magico.matadora-de-dragoes","nome":"Matadora de Dragões","tipo":"Arma","rar":"Raro","sint":"","desc":"Arma +1 que causa +3d6 de dano contra dragões."},
{"id":"magico.matadora-de-gigantes","nome":"Matadora de Gigantes","tipo":"Arma","rar":"Raro","sint":"","desc":"Arma +1 que causa +2d6 contra gigantes, e o gigante atingido faz teste de Força CD 15 ou cai no chão."},
{"id":"magico.maca-da-ruptura","nome":"Maça da Ruptura","tipo":"Arma","rar":"Raro","sint":"Sim","desc":"Contra demônios e mortos-vivos causa +2d6 radiante. Se o alvo ficar com 25 PV ou menos, faz teste de Sabedoria CD 15 ou é destruído na hora. Também ilumina como uma tocha."},
{"id":"magico.maca-do-esmagamento","nome":"Maça do Esmagamento","tipo":"Arma","rar":"Raro","sint":"","desc":"Maça +1 (+3 contra constructos). Num 20 natural, causa +7 de dano (+14 em constructos) e pode destruir constructos enfraquecidos."},
{"id":"magico.maca-do-terror","nome":"Maça do Terror","tipo":"Arma","rar":"Raro","sint":"Sim","desc":"Tem 3 cargas. Gastando uma, solta uma onda de medo: quem você escolher a até 9 m faz teste de Sabedoria CD 15 ou fica amedrontado e foge por 1 minuto."},
{"id":"magico.municao-1-2-ou-3","nome":"Munição +1, +2 ou +3","tipo":"Arma","rar":"Varia","sint":"","desc":"Flechas, virotes ou balas encantadas que dão bônus no ataque e no dano (+1 incomum, +2 rara, +3 muito rara). Depois que acerta o alvo, a peça perde a magia. Costuma vir em lotes de 10 ou 20."},
{"id":"magico.municao-assassina","nome":"Munição Assassina","tipo":"Arma","rar":"Muito raro","sint":"","desc":"Munição feita pra matar um tipo específico de criatura (dragões, demônios, mortos-vivos, gigantes…), escolhido pelo mestre. Se uma criatura desse tipo levar dano dela, faz teste de Constituição CD 17: +6d10 de energia, ou metade se passar. Depois de causar esse dano extra, vira munição comum."},
{"id":"magico.tridente-do-comando-aquatico","nome":"Tridente do Comando Aquático","tipo":"Arma","rar":"Incomum","sint":"Sim","desc":"Tem 3 cargas pra lançar Dominar Fera (CD 15) em criaturas que nadam."},
{"id":"magico.vingadora-sagrada","nome":"Vingadora Sagrada","tipo":"Arma","rar":"Lendário","sint":"Sim (só Paladino)","desc":"Arma lendária de paladino, +3. Causa +2d10 radiante em demônios e mortos-vivos e, empunhada, cria uma aura de 3 m que dá aos aliados vantagem contra magias e efeitos mágicos."},
{"id":"magico.armadura-1-2-ou-3","nome":"Armadura +1, +2 ou +3","tipo":"Armadura","rar":"Varia","sint":"","desc":"Qualquer armadura leve, média ou pesada encantada. Dá +1 (rara), +2 (muito rara) ou +3 (lendária) na CA, além da proteção normal dela."},
{"id":"magico.armadura-demoniaca","nome":"Armadura Demoníaca","tipo":"Armadura","rar":"Muito raro","sint":"Sim","desc":"Dá +1 na CA, você entende a língua dos demônios e as manoplas com garras fazem seus golpes desarmados causarem 1d8 cortante com +1. Mas é amaldiçoada: não sai do corpo e dá desvantagem contra magias e habilidades de demônios."},
{"id":"magico.armadura-da-invulnerabilidade","nome":"Armadura da Invulnerabilidade","tipo":"Armadura","rar":"Lendário","sint":"Sim","desc":"Armadura de placas que dá resistência a dano de concussão, perfurante e cortante. Uma vez por dia, com uma ação, você fica imune a esses três tipos de dano por 10 minutos."},
{"id":"magico.armadura-da-vulnerabilidade","nome":"Armadura da Vulnerabilidade","tipo":"Armadura","rar":"Raro","sint":"Sim","desc":"Parece ótima: dá resistência a dano de concussão, perfurante ou cortante. Mas é amaldiçoada: você fica vulnerável aos outros dois tipos e não consegue tirá-la até quebrarem a maldição com Remover Maldição."},
{"id":"magico.armadura-de-placas-eterea","nome":"Armadura de Placas Etérea","tipo":"Armadura","rar":"Lendário","sint":"Sim","desc":"Armadura de placas (ou meia armadura) que, uma vez por dia, com uma palavra, te leva ao Plano Etéreo como a magia Forma Etérea."},
{"id":"magico.armadura-de-resistencia","nome":"Armadura de Resistência","tipo":"Armadura","rar":"Raro","sint":"Sim","desc":"Armadura leve, média ou pesada que dá resistência a um tipo de dano (ácido, frio, fogo, energia, raio, necrótico, veneno, psíquico, radiante ou trovão), escolhido pelo mestre ou sorteado."},
{"id":"magico.brunea-de-escamas-de-dragao","nome":"Brunea de Escamas de Dragão","tipo":"Armadura","rar":"Muito raro","sint":"Sim","desc":"Feita das escamas de um tipo de dragão. Dá +1 na CA, resistência ao tipo de dano daquele dragão e vantagem contra sopros de dragão. Uma vez por dia, também te ajuda a localizar o dragão mais próximo daquele tipo."},
{"id":"magico.cota-elfica","nome":"Cota Élfica","tipo":"Armadura","rar":"Raro","sint":"","desc":"Malha élfica levíssima que dá +1 na CA. Conta como se você tivesse treino com ela mesmo sem saber usar armaduras médias ou pesadas."},
{"id":"magico.couro-batido-encantado","nome":"Couro Batido Encantado","tipo":"Armadura","rar":"Raro","sint":"","desc":"Couro batido +1 que, com uma ação bônus, muda de aparência pra parecer roupa comum ou outra armadura qualquer."},
{"id":"magico.placas-anas","nome":"Placas Anãs","tipo":"Armadura","rar":"Muito raro","sint":"","desc":"Armadura pesada que dá +2 na CA. Se algo tentar te empurrar contra a vontade, você usa a reação pra reduzir a distância em até 3 m."},
{"id":"magico.escudo-1-2-ou-3","nome":"Escudo +1, +2 ou +3","tipo":"Escudo","rar":"Varia","sint":"","desc":"Escudo encantado que soma +1 (incomum), +2 (raro) ou +3 (muito raro) na CA, além dos +2 normais do escudo."},
{"id":"magico.escudo-animado","nome":"Escudo Animado","tipo":"Escudo","rar":"Muito raro","sint":"Sim","desc":"Com uma ação bônus, o escudo sai voando e fica flutuando na sua frente, protegendo como se estivesse no seu braço e deixando suas mãos livres. Fica assim por 1 minuto, até você encerrar ou ficar incapacitado."},
{"id":"magico.escudo-antimagia","nome":"Escudo Antimagia","tipo":"Escudo","rar":"Muito raro","sint":"Sim","desc":"Dá vantagem em testes contra magias e efeitos mágicos, e ataques mágicos contra você têm desvantagem."},
{"id":"magico.escudo-atrai-projeteis","nome":"Escudo Atrai-Projéteis","tipo":"Escudo","rar":"Raro","sint":"Sim","desc":"Dá resistência a dano de armas à distância. Mas é amaldiçoado: sempre que alguém a até 3 m for alvo de um ataque à distância, o ataque vem em você."},
{"id":"magico.escudo-pega-flechas","nome":"Escudo Pega-Flechas","tipo":"Escudo","rar":"Raro","sint":"Sim","desc":"Escudo que dá +2 extra na CA contra ataques à distância. Quando alguém ao seu lado (até 1,5 m) for alvo de um ataque à distância, você pode usar sua reação pra virar o alvo no lugar dele."},
{"id":"magico.escudo-sentinela","nome":"Escudo Sentinela","tipo":"Escudo","rar":"Incomum","sint":"","desc":"Escudo com um olho pintado. Dá vantagem em iniciativa e Percepção."},
{"id":"magico.escudo-do-cavaleiro","nome":"Escudo do Cavaleiro","tipo":"Escudo","rar":"Muito raro","sint":"Sim","desc":"Dá +2 extra na CA. Dá pra atacar com ele empurrando o alvo, e uma vez por dia ele cria uma barreira protetora que bloqueia ataques e magias ao seu redor."},
{"id":"magico.anel-armazenador-de-magias","nome":"Anel Armazenador de Magias","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Guarda até 5 círculos de magias que alguém conjurar nele. Depois, quem usa o anel pode lançar essas magias como se fossem suas, com a CD de quem guardou. Ótimo pra deixar uma cura ou um escudo de reserva com o guerreiro."},
{"id":"magico.anel-da-evasao","nome":"Anel da Evasão","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Tem 3 cargas. Quando você falha num teste de Destreza, usa a reação e gasta uma carga pra passar no lugar."},
{"id":"magico.anel-da-influencia-animal","nome":"Anel da Influência Animal","tipo":"Anel","rar":"Raro","sint":"","desc":"Tem 3 cargas pra lançar Amizade Animal, Medo (só em animais) ou Falar com Animais (CD 13). Recupera 1d3 por dia."},
{"id":"magico.anel-da-invisibilidade","nome":"Anel da Invisibilidade","tipo":"Anel","rar":"Lendário","sint":"Sim","desc":"Com uma ação, você fica invisível até tirar o anel ou decidir aparecer de novo (ação bônus). Diferente da magia, não acaba quando você ataca."},
{"id":"magico.anel-da-movimentacao-livre","nome":"Anel da Movimentação Livre","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Terreno difícil não te atrasa, e nenhuma magia consegue reduzir seu deslocamento, te paralisar ou te conter."},
{"id":"magico.anel-da-natacao","nome":"Anel da Natação","tipo":"Anel","rar":"Incomum","sint":"","desc":"Você nada a 12 m por turno."},
{"id":"magico.anel-da-protecao","nome":"Anel da Proteção","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Dá +1 na CA e em todos os testes de resistência."},
{"id":"magico.anel-da-protecao-mental","nome":"Anel da Proteção Mental","tipo":"Anel","rar":"Incomum","sint":"Sim","desc":"Ninguém lê seus pensamentos, descobre se você mente ou sabe sua natureza. Se você morrer usando o anel, sua alma pode ficar morando dentro dele."},
{"id":"magico.anel-da-queda-suave","nome":"Anel da Queda Suave","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Quando você cai, desce devagar (18 m por rodada) e não sofre dano da queda."},
{"id":"magico.anel-da-reflexao-de-magias","nome":"Anel da Reflexão de Magias","tipo":"Anel","rar":"Lendário","sint":"Sim","desc":"Dá vantagem contra magias. Se você passar no teste contra uma magia de até 7º círculo, ela não te afeta, e se tiver mirado só você, você pode usar a reação pra devolvê-la a quem lançou."},
{"id":"magico.anel-da-regeneracao","nome":"Anel da Regeneração","tipo":"Anel","rar":"Muito raro","sint":"Sim","desc":"Você recupera 1d6 PV a cada 10 minutos (se tiver pelo menos 1 PV), e partes do corpo perdidas crescem de novo em alguns dias."},
{"id":"magico.anel-da-resistencia","nome":"Anel da Resistência","tipo":"Anel","rar":"Raro","sint":"","desc":"Dá resistência a um tipo de dano, indicado pela pedra do anel: pérola (ácido), turmalina (frio), granada (fogo), safira (energia), citrino (raio), azeviche (necrótico) e outras."},
{"id":"magico.anel-da-telecinesia","nome":"Anel da Telecinésia","tipo":"Anel","rar":"Muito raro","sint":"Sim","desc":"Você pode lançar Telecinésia quando quiser."},
{"id":"magico.anel-da-visao-de-raio-x","nome":"Anel da Visão de Raio X","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Com uma ação, você enxerga através de paredes e objetos num raio de 9 m por 1 minuto (até 30 cm de pedra ou 2,5 cm de metal). Usar mais de uma vez por dia cansa: teste de Constituição ou exaustão."},
{"id":"magico.anel-das-estrelas-cadentes","nome":"Anel das Estrelas Cadentes","tipo":"Anel","rar":"Muito raro","sint":"Sim","desc":"Lança Luz e Luzes Dançantes à vontade. Com cargas, lança Fogo das Fadas, cria esferas de raio que voam e explodem, ou solta estrelas cadentes que explodem em luz e fogo. Só funciona à noite ou no escuro."},
{"id":"magico.anel-de-andar-na-agua","nome":"Anel de Andar na Água","tipo":"Anel","rar":"Incomum","sint":"","desc":"Você pode lançar Caminhar sobre as Águas em si mesmo quando quiser."},
{"id":"magico.anel-de-invocacao-do-genio","nome":"Anel de Invocação do Gênio","tipo":"Anel","rar":"Lendário","sint":"Sim","desc":"Invoca um djinni, um gênio do ar, que te serve por até 1 hora enquanto você se concentra. Se o anel for destruído, o gênio fica livre."},
{"id":"magico.anel-do-ariete","nome":"Anel do Aríete","tipo":"Anel","rar":"Raro","sint":"Sim","desc":"Tem 3 cargas. Gastando de 1 a 3, uma cabeça de carneiro fantasma ataca alguém a até 18 m: 2d10 de energia por carga e empurrão. Também ajuda a arrombar portas."},
{"id":"magico.anel-do-calor","nome":"Anel do Calor","tipo":"Anel","rar":"Incomum","sint":"Sim","desc":"Reduz em 2d8 todo dano de frio que você sofrer, e você aguenta temperaturas congelantes sem problemas."},
{"id":"magico.anel-do-comando-elemental","nome":"Anel do Comando Elemental","tipo":"Anel","rar":"Lendário","sint":"Sim","desc":"Ligado a um plano elemental (ar, terra, fogo ou água). Dá vantagem contra elementais daquele tipo, deixa você falar a língua deles e lançar magias ligadas ao elemento, como Relâmpago, Muralha de Fogo ou Controlar Água."},
{"id":"magico.anel-do-salto","nome":"Anel do Salto","tipo":"Anel","rar":"Incomum","sint":"Sim","desc":"Você pode lançar Salto em si mesmo quando quiser."},
{"id":"magico.anel-dos-tres-desejos","nome":"Anel dos Três Desejos","tipo":"Anel","rar":"Lendário","sint":"","desc":"Tem 3 cargas, e cada uma lança Desejo. Depois da última, vira um anel comum. Um dos itens mais poderosos que existem."},
{"id":"magico.elixir-da-saude","nome":"Elixir da Saúde","tipo":"Poção","rar":"Raro","sint":"","desc":"Líquido vermelho com bolhinhas de luz. Cura doenças mágicas e acaba com cegueira, surdez, paralisia e envenenamento."},
{"id":"magico.filtro-do-amor","nome":"Filtro do Amor","tipo":"Poção","rar":"Incomum","sint":"","desc":"Um líquido rosado com uma bolha em forma de coração. Quem bebe fica enfeitiçado pela primeira criatura que vir nos próximos 10 minutos, por 1 hora."},
{"id":"magico.pocao-venenosa","nome":"Poção Venenosa","tipo":"Poção","rar":"Incomum","sint":"","desc":"Parece, cheira e tem gosto de poção de cura, mas é veneno disfarçado por ilusão. Quem bebe sofre 4d6 de veneno e faz teste de Constituição ou fica envenenado. Identificação revela a verdade."},
{"id":"magico.pocao-da-amizade-animal","nome":"Poção da Amizade Animal","tipo":"Poção","rar":"Incomum","sint":"","desc":"Quem bebe pode lançar Amizade Animal de 3º círculo (CD 13). O líquido barrento tem escamas, penas e pelos de bichos boiando."},
{"id":"magico.pocao-da-clarividencia","nome":"Poção da Clarividência","tipo":"Poção","rar":"Raro","sint":"","desc":"Dá o efeito de Clarividência sem precisar de concentração. Tem um olho boiando dentro, que some quando abre."},
{"id":"magico.pocao-da-diminuicao","nome":"Poção da Diminuição","tipo":"Poção","rar":"Raro","sint":"","desc":"Você encolhe como no efeito Reduzir da magia Aumentar/Reduzir, por 1d4 horas, sem precisar de concentração."},
{"id":"magico.pocao-da-escalada","nome":"Poção da Escalada","tipo":"Poção","rar":"Comum","sint":"","desc":"Por 1 hora, você escala tão rápido quanto anda e tem vantagem pra escalar. O líquido tem camadas de cor como rocha."},
{"id":"magico.pocao-da-forma-gasosa","nome":"Poção da Forma Gasosa","tipo":"Poção","rar":"Raro","sint":"","desc":"Por 1 hora você vira névoa, como na magia Forma Gasosa, sem precisar de concentração. Dá pra encerrar com uma ação bônus."},
{"id":"magico.pocao-da-forca-de-gigante","nome":"Poção da Força de Gigante","tipo":"Poção","rar":"Varia","sint":"","desc":"Por 1 hora, sua Força vira a de um gigante, de 21 (colina) a 29 (tempestade), conforme a poção. Não faz nada se a sua já for maior."},
{"id":"magico.pocao-da-invisibilidade","nome":"Poção da Invisibilidade","tipo":"Poção","rar":"Raro","sint":"","desc":"O frasco parece vazio. Quem bebe fica invisível por 1 hora, até atacar, causar dano ou conjurar."},
{"id":"magico.pocao-da-invulnerabilidade","nome":"Poção da Invulnerabilidade","tipo":"Poção","rar":"Raro","sint":"","desc":"Por 1 minuto, você tem resistência a todo tipo de dano. O líquido parece ferro derretido."},
{"id":"magico.pocao-da-leitura-mental","nome":"Poção da Leitura Mental","tipo":"Poção","rar":"Raro","sint":"","desc":"Por 10 minutos, você tem o efeito de Detectar Pensamentos (CD 13), sem precisar de concentração."},
{"id":"magico.pocao-da-longevidade","nome":"Poção da Longevidade","tipo":"Poção","rar":"Muito raro","sint":"","desc":"Você rejuvenesce 1d6 + 6 anos. Mas a cada poção extra que tomar, há 10% de chance acumulada de envelhecer em vez disso."},
{"id":"magico.pocao-da-resistencia","nome":"Poção da Resistência","tipo":"Poção","rar":"Incomum","sint":"","desc":"Por 1 hora, você tem resistência a um tipo de dano (ácido, frio, fogo, energia, raio, necrótico, veneno, psíquico, radiante ou trovão), definido pela poção."},
{"id":"magico.pocao-da-respiracao-aquatica","nome":"Poção da Respiração Aquática","tipo":"Poção","rar":"Incomum","sint":"","desc":"Você respira debaixo d'água por 24 horas. Tem cheiro de mar e uma bolha parecida com água-viva."},
{"id":"magico.pocao-da-velocidade","nome":"Poção da Velocidade","tipo":"Poção","rar":"Muito raro","sint":"","desc":"Por 1 minuto, você tem o efeito de Velocidade, sem precisar de concentração e sem o cansaço quando acaba."},
{"id":"magico.pocao-da-vitalidade","nome":"Poção da Vitalidade","tipo":"Poção","rar":"Muito raro","sint":"","desc":"Remove toda a exaustão e o envenenamento. Por 24 horas, todo dado de vida que você gastar cura o máximo."},
{"id":"magico.pocao-do-crescimento","nome":"Poção do Crescimento","tipo":"Poção","rar":"Incomum","sint":"","desc":"Por 10 minutos, você cresce como no efeito Aumentar da magia Aumentar/Reduzir, sem precisar de concentração."},
{"id":"magico.pocao-do-heroismo","nome":"Poção do Heroísmo","tipo":"Poção","rar":"Raro","sint":"","desc":"Por 1 hora, você ganha 10 PV temporários e fica sob efeito de Bênção (+1d4 em ataques e resistências), sem precisar de concentração."},
{"id":"magico.pocao-do-voo","nome":"Poção do Voo","tipo":"Poção","rar":"Muito raro","sint":"","desc":"Por 1 hora, você voa na mesma velocidade que anda e pode pairar. Se estiver no ar quando acabar, cai."},
{"id":"magico.pocoes-de-cura-todas","nome":"Poções de Cura (todas)","tipo":"Poção","rar":"Varia","sint":"","desc":"A poção clássica, de líquido vermelho que brilha. Cura 2d4+2 (comum), 4d4+4 (maior, incomum), 8d4+8 (superior, rara) ou 10d4+20 PV (suprema, muito rara). Beber leva uma ação bônus."},
{"id":"magico.oleo-escorregadio","nome":"Óleo Escorregadio","tipo":"Poção","rar":"Incomum","sint":"","desc":"Passado no corpo, dá o efeito de Movimentação Livre por 8 horas. Derramado no chão, vira uma área escorregadia como a magia Área Escorregadia."},
{"id":"magico.oleo-da-afiacao","nome":"Óleo da Afiação","tipo":"Poção","rar":"Muito raro","sint":"","desc":"Passado numa arma cortante ou perfurante (ou em 20 munições), transforma ela em arma +3 por 1 hora."},
{"id":"magico.oleo-da-forma-eterea","nome":"Óleo da Forma Etérea","tipo":"Poção","rar":"Raro","sint":"","desc":"Passando o óleo no corpo (10 minutos), você entra no Plano Etéreo por 1 hora, como na magia Forma Etérea."},
{"id":"magico.varinha-da-amarracao","nome":"Varinha da Amarração","tipo":"Varinha","rar":"Raro","sint":"Sim","desc":"Tem 7 cargas pra lançar Imobilizar Pessoa e Imobilizar Monstro (CD 17). Também ajuda a escapar de prisões."},
{"id":"magico.varinha-da-deteccao-de-inimigos","nome":"Varinha da Detecção de Inimigos","tipo":"Varinha","rar":"Raro","sint":"Sim","desc":"Tem 7 cargas. Por 1 minuto, aponta a direção do inimigo mais próximo a até 18 m, mesmo invisível ou disfarçado."},
{"id":"magico.varinha-da-deteccao-de-magia","nome":"Varinha da Detecção de Magia","tipo":"Varinha","rar":"Incomum","sint":"","desc":"Tem 3 cargas pra lançar Detectar Magia. Recupera 1d3 por dia."},
{"id":"magico.varinha-da-metamorfose","nome":"Varinha da Metamorfose","tipo":"Varinha","rar":"Muito raro","sint":"Sim (só conjurador)","desc":"Tem 7 cargas pra lançar Metamorfose (CD 15)."},
{"id":"magico.varinha-da-paralisia","nome":"Varinha da Paralisia","tipo":"Varinha","rar":"Raro","sint":"Sim (só conjurador)","desc":"Tem 7 cargas. Cada uma dispara um raio azul: o alvo faz teste de Constituição CD 15 ou fica paralisado por 1 minuto."},
{"id":"magico.varinha-das-bolas-de-fogo","nome":"Varinha das Bolas de Fogo","tipo":"Varinha","rar":"Raro","sint":"Sim (só conjurador)","desc":"Tem 7 cargas pra lançar Bola de Fogo (CD 15), gastando mais cargas pra aumentar o círculo. Gastar a última pode destruí-la."},
{"id":"magico.varinha-das-maravilhas","nome":"Varinha das Maravilhas","tipo":"Varinha","rar":"Raro","sint":"Sim","desc":"Cada carga solta um efeito aleatório, rolado numa tabela: de uma Bola de Fogo a uma chuva de borboletas, de deixar você invisível a fazer crescer grama na área. Caótica e divertida."},
{"id":"magico.varinha-das-teias","nome":"Varinha das Teias","tipo":"Varinha","rar":"Incomum","sint":"Sim (só conjurador)","desc":"Tem 7 cargas pra lançar Teia (CD 13)."},
{"id":"magico.varinha-do-mago-de-guerra-1-2-ou-3","nome":"Varinha do Mago de Guerra +1, +2 ou +3","tipo":"Varinha","rar":"Varia","sint":"Sim (só conjurador)","desc":"Dá +1, +2 ou +3 nos ataques mágicos e faz você ignorar meia cobertura."},
{"id":"magico.varinha-do-medo","nome":"Varinha do Medo","tipo":"Varinha","rar":"Raro","sint":"Sim","desc":"Tem 7 cargas pra lançar Comando (\"fuja\" ou \"deite\") e Medo num cone grande (CD 15)."},
{"id":"magico.varinha-dos-misseis-magicos","nome":"Varinha dos Mísseis Mágicos","tipo":"Varinha","rar":"Incomum","sint":"","desc":"Tem 7 cargas pra lançar Mísseis Mágicos, gastando mais cargas pra aumentar o círculo."},
{"id":"magico.varinha-dos-relampagos","nome":"Varinha dos Relâmpagos","tipo":"Varinha","rar":"Raro","sint":"Sim (só conjurador)","desc":"Tem 7 cargas pra lançar Relâmpago (CD 15), gastando mais cargas pra aumentar o círculo. Gastar a última pode destruí-la."},
{"id":"magico.varinha-dos-segredos","nome":"Varinha dos Segredos","tipo":"Varinha","rar":"Incomum","sint":"","desc":"Tem 3 cargas. Aponta a porta secreta ou armadilha mais próxima a até 18 m."},
{"id":"magico.cajado-da-cura","nome":"Cajado da Cura","tipo":"Cajado","rar":"Raro","sint":"Sim (só Bardo, Clérigo ou Druida)","desc":"Tem 10 cargas pra lançar Curar Ferimentos, Restauração Menor e Curar Ferimentos em Massa. Pra bardos, clérigos e druidas."},
{"id":"magico.cajado-da-piton","nome":"Cajado da Píton","tipo":"Cajado","rar":"Incomum","sint":"Sim","desc":"Arremessado, vira uma serpente constritora gigante que obedece você. Se ela morrer, o cajado é destruído."},
{"id":"magico.cajado-das-florestas","nome":"Cajado das Florestas","tipo":"Cajado","rar":"Raro","sint":"Sim (só Druida)","desc":"Pra druidas. Bordão +2 com 6 cargas pra lançar magias da natureza, como Falar com Animais, Pele de Árvore e Despertar. Também pode virar uma árvore de verdade."},
{"id":"magico.cajado-do-arquimago","nome":"Cajado do Arquimago","tipo":"Cajado","rar":"Lendário","sint":"Sim (só Feiticeiro, Bruxo ou Mago)","desc":"O cajado mais poderoso. Bordão +2, +2 em ataques mágicos, absorve magias lançadas contra você e tem 50 cargas pra lançar dezenas de magias. Pode ser quebrado numa explosão enorme que talvez te leve pra outro plano."},
{"id":"magico.cajado-do-definhamento","nome":"Cajado do Definhamento","tipo":"Cajado","rar":"Raro","sint":"Sim","desc":"Bordão com 3 cargas. Ao acertar, gasta uma pra causar +2d10 necrótico e o alvo faz teste de Constituição ou tem desvantagem em Força e Constituição por 1 hora."},
{"id":"magico.cajado-do-encantamento","nome":"Cajado do Encantamento","tipo":"Cajado","rar":"Raro","sint":"Sim (só Bardo, Clérigo, Druida, Feiticeiro, Bruxo ou Mago)","desc":"Tem 10 cargas pra lançar Enfeitiçar Pessoa, Comando ou Compreender Idiomas. Se você passar num teste contra encantamento, pode refletir o efeito de volta."},
{"id":"magico.cajado-do-fogo","nome":"Cajado do Fogo","tipo":"Cajado","rar":"Muito raro","sint":"Sim (só Druida, Feiticeiro, Bruxo ou Mago)","desc":"Dá resistência a fogo e tem 10 cargas pra lançar Mãos Flamejantes, Bola de Fogo e Muralha de Fogo. Gastar a última carga pode destruí-lo em chamas."},
{"id":"magico.cajado-do-gelo","nome":"Cajado do Gelo","tipo":"Cajado","rar":"Muito raro","sint":"Sim (só Druida, Feiticeiro, Bruxo ou Mago)","desc":"Dá resistência a frio e tem 10 cargas pra lançar Névoa Obscurecente, Tempestade de Gelo, Muralha de Gelo e Cone de Frio."},
{"id":"magico.cajado-do-golpe","nome":"Cajado do Golpe","tipo":"Cajado","rar":"Muito raro","sint":"Sim","desc":"Bordão +3. Ao acertar, você gasta até 3 cargas pra causar +1d6 de energia por carga."},
{"id":"magico.cajado-do-poder","nome":"Cajado do Poder","tipo":"Cajado","rar":"Muito raro","sint":"Sim (só Feiticeiro, Bruxo ou Mago)","desc":"Bordão +2 que dá +2 na CA, nas resistências e nos ataques mágicos. Tem 20 cargas pra lançar várias magias de ataque e defesa. Pode ser quebrado de propósito numa explosão devastadora."},
{"id":"magico.cajado-do-trovao-e-relampago","nome":"Cajado do Trovão e Relâmpago","tipo":"Cajado","rar":"Muito raro","sint":"Sim","desc":"Bordão +2 com cinco poderes, cada um uma vez por dia: raio extra no golpe, trovão que ensurdece, relâmpago em linha, trovoada em área e os dois juntos."},
{"id":"magico.cajado-dos-insetos","nome":"Cajado dos Insetos","tipo":"Cajado","rar":"Raro","sint":"Sim (só Bardo, Clérigo, Druida, Feiticeiro, Bruxo ou Mago)","desc":"Tem 10 cargas. Cria uma nuvem de insetos que bloqueia a visão ao seu redor ou lança Praga de Insetos e Inseto Gigante."},
{"id":"magico.bastao-imovel","nome":"Bastão Imóvel","tipo":"Bastão","rar":"Incomum","sint":"","desc":"Um bastão de ferro com um botão. Apertando, ele trava no ar e não sai do lugar, aguentando até 4 toneladas. Ótimo pra travar portas, montar escadas e inventar soluções."},
{"id":"magico.bastao-da-absorcao","nome":"Bastão da Absorção","tipo":"Bastão","rar":"Muito raro","sint":"Sim","desc":"Com a reação, absorve uma magia que mira só você: ela é cancelada e a energia fica guardada no bastão. Depois, você pode usar essa energia pra conjurar suas próprias magias sem gastar espaço."},
{"id":"magico.bastao-da-ressurreicao","nome":"Bastão da Ressurreição","tipo":"Bastão","rar":"Lendário","sint":"Sim","desc":"Tem 5 cargas pra lançar Cura Completa (1 carga) ou Ressurreição (5 cargas). Recupera 1 por dia."},
{"id":"magico.bastao-da-seguranca","nome":"Bastão da Segurança","tipo":"Bastão","rar":"Muito raro","sint":"","desc":"Leva você e até 199 criaturas pra um semiplano tranquilo (jardim, taverna, palácio, praia) onde ninguém precisa comer e todos se curam. Ficam lá até 200 dias divididos pelo número de pessoas."},
{"id":"magico.bastao-da-vigilancia","nome":"Bastão da Vigilância","tipo":"Bastão","rar":"Muito raro","sint":"Sim","desc":"Dá vantagem em Percepção e iniciativa, lança várias magias de detecção e, uma vez por dia, espalha olhos e proteções num raio de 36 m pra vigiar o acampamento."},
{"id":"magico.bastao-do-dominio","nome":"Bastão do Domínio","tipo":"Bastão","rar":"Raro","sint":"Sim","desc":"Uma vez por dia, quem você escolher a até 36 m faz teste de Sabedoria CD 15 ou fica enfeitiçado e te trata como um líder confiável por 8 horas."},
{"id":"magico.bastao-do-poder-senhorial","nome":"Bastão do Poder Senhorial","tipo":"Bastão","rar":"Lendário","sint":"Sim","desc":"Uma maça +3 com seis botões: vira espada, machado, lança ou escada telescópica, aponta o norte, mede profundidade e tem poderes de paralisar, assustar e drenar vida. A ferramenta suprema."},
{"id":"magico.pergaminho-de-magia","nome":"Pergaminho de Magia","tipo":"Pergaminho","rar":"Varia","sint":"","desc":"Um pergaminho com uma magia escrita. Se a magia estiver na sua lista, você a conjura lendo o texto, sem componentes. Se for de círculo maior do que você consegue, faz um teste de conjuração. Depois de usado, se desfaz. A raridade depende do círculo."},
{"id":"magico.algemas-dimensionais","nome":"Algemas Dimensionais","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Algemas que, presas em alguém incapacitado, impedem qualquer teletransporte ou viagem entre planos. Abrir sem a chave é muito difícil."},
{"id":"magico.aljava-eficiente","nome":"Aljava Eficiente","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Uma aljava com três compartimentos extradimensionais: até 60 flechas, 18 azagaias e 6 objetos longos (arcos, bordões, lanças). Nunca pesa mais de 1 kg."},
{"id":"magico.amuleto-contra-deteccao","nome":"Amuleto Contra Detecção","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Enquanto usar este amuleto, nenhuma magia de adivinhação consegue te mirar e nenhum sensor mágico consegue te espiar, a não ser que você deixe."},
{"id":"magico.amuleto-da-saude","nome":"Amuleto da Saúde","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Enquanto usar este amuleto, sua Constituição passa a ser 19. Não faz nada se a sua já for 19 ou mais."},
{"id":"magico.amuleto-dos-planos","nome":"Amuleto dos Planos","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Com uma ação, você diz o nome de um lugar conhecido em outro plano e faz um teste de Arcanismo CD 15. Se passar, viaja pra lá como em Viagem Planar. Se falhar, você e tudo ao seu redor são jogados num plano aleatório, o que pode dar muito errado."},
{"id":"magico.aparato-do-caranguejo","nome":"Aparato do Caranguejo","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Parece um barril de ferro de 250 kg, mas esconde uma trava secreta. Por dentro, duas pessoas pequenas ou médias controlam com dez alavancas um caranguejo mecânico gigante que anda, nada, agarra com as pinças e ilumina o caminho. Um submarino de fantasia."},
{"id":"magico.asas-do-voo","nome":"Asas do Voo","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Um manto que vira um par de asas: voo de 18 m por turno por 1 hora. Depois precisa descansar."},
{"id":"magico.baralho-misterioso","nome":"Baralho Misterioso","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Um baralho lendário e perigoso. Você declara quantas cartas vai tirar, e cada uma tem um efeito poderoso e imprevisível: ganhar riquezas, um item lendário ou um desejo, ou perder tudo, ganhar um inimigo mortal ou ter a alma aprisionada. Muda campanhas inteiras."},
{"id":"magico.baralho-das-ilusoes","nome":"Baralho das Ilusões","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Cartas que, arremessadas, viram a ilusão de uma criatura (um dragão, um troll, um rei) por até 1 hora. As ilusões parecem reais, mas não causam dano. Um baralho achado costuma estar incompleto."},
{"id":"magico.barco-dobravel","nome":"Barco Dobrável","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Uma caixinha de madeira de 30 cm. Com uma palavra, vira um bote a remo; com outra, um barco de quilha com vela; com a terceira, volta a ser caixa."},
{"id":"magico.bola-de-cristal","nome":"Bola de Cristal","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Tocando o cristal, você lança Vidência (CD 17) quando quiser."},
{"id":"magico.bola-de-cristal-da-leitura-mental","nome":"Bola de Cristal da Leitura Mental","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Lança Vidência (CD 17) e, pelo sensor, também Detectar Pensamentos em quem estiver perto dele, sem precisar de concentração extra."},
{"id":"magico.bola-de-cristal-da-telepatia","nome":"Bola de Cristal da Telepatia","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Lança Vidência (CD 17) e, pelo sensor, você conversa por telepatia com quem estiver perto dele e pode lançar Sugestão em um deles."},
{"id":"magico.bola-de-cristal-da-visao-verdadeira","nome":"Bola de Cristal da Visão Verdadeira","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Lança Vidência (CD 17) e você enxerga com visão verdadeira ao redor do sensor, vendo através de ilusões e invisibilidade."},
{"id":"magico.bolsa-guarda-tudo","nome":"Bolsa Guarda-Tudo","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Uma bolsa muito maior por dentro do que por fora: guarda até 250 kg (uns 1.800 litros) e sempre pesa 2,5 kg. Pegar algo dentro leva uma ação. Se for rasgada ou colocada dentro de outro espaço extradimensional (como um Buraco Portátil), é destruída e pode abrir um portal pro Plano Astral."},
{"id":"magico.botas-aladas","nome":"Botas Aladas","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Têm 4 cargas. Gastando uma, você voa a 9 m por turno por 1 hora."},
{"id":"magico.botas-da-levitacao","nome":"Botas da Levitação","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Enquanto usar, você pode lançar Levitação em si mesmo quando quiser."},
{"id":"magico.botas-da-velocidade","nome":"Botas da Velocidade","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Com uma ação bônus você bate os calcanhares: seu deslocamento dobra e ataques de oportunidade contra você têm desvantagem. Funciona por até 10 minutos no total, e recarrega depois de um descanso longo."},
{"id":"magico.botas-das-terras-geladas","nome":"Botas das Terras Geladas","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Botas de pele quentinhas. Dão resistência a frio, deixam você aguentar temperaturas muito baixas e ignorar terreno difícil de gelo e neve."},
{"id":"magico.botas-de-saltos-e-passadas","nome":"Botas de Saltos e Passadas","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Seu deslocamento passa a ser no mínimo 9 m e não diminui por peso ou armadura pesada. Uma vez por turno, você salta até 9 m gastando só 3 m de movimento."},
{"id":"magico.botas-elficas","nome":"Botas Élficas","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Seus passos não fazem nenhum barulho, em qualquer superfície, e você tem vantagem em Furtividade."},
{"id":"magico.braceletes-de-arquearia","nome":"Braceletes de Arquearia","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Dão proficiência com arco curto e arco longo, e +2 no dano com eles."},
{"id":"magico.braceletes-de-defesa","nome":"Braceletes de Defesa","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Dão +2 na CA enquanto você não estiver usando armadura nem escudo. Os favoritos de monges e magos."},
{"id":"magico.braseiro-dos-elementais-do-fogo","nome":"Braseiro dos Elementais do Fogo","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Perto do braseiro aceso, você invoca um elemental do fogo que obedece suas ordens por 1 hora. Só funciona uma vez por dia."},
{"id":"magico.broche-do-escudo","nome":"Broche do Escudo","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Dá resistência a dano de energia e imunidade a Mísseis Mágicos."},
{"id":"magico.buraco-portatil","nome":"Buraco Portátil","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Um pano preto do tamanho de um lenço que, aberto no chão ou na parede, vira um buraco de 3 m de profundidade e 1,8 m de largura. Dá pra dobrar com tudo dentro. Se for colocado dentro de uma Bolsa Guarda-Tudo, os dois são destruídos e abrem um portal pro Plano Astral."},
{"id":"magico.capa-do-charlatao","nome":"Capa do Charlatão","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Uma capa com cheiro de enxofre. Uma vez por dia, ela lança Porta Dimensional e deixa uma nuvem de fumaça no lugar de onde você sumiu."},
{"id":"magico.chapeu-das-muitas-magias","nome":"Chapéu das Muitas Magias","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim (só Mago)","desc":"Chapéu pontudo de mago que serve de foco: você \"puxa\" as magias de dentro dele. Também dá pra tentar tirar do chapéu uma magia que você nem conhece, com resultado imprevisível, às vezes até um animal."},
{"id":"magico.chapeu-do-disfarce","nome":"Chapéu do Disfarce","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Enquanto usar, você pode lançar Disfarçar-se quando quiser. A magia acaba se tirar o chapéu."},
{"id":"magico.cinto-de-forca-de-gigante","nome":"Cinto de Força de Gigante","tipo":"Item maravilhoso","rar":"Varia","sint":"Sim","desc":"Sua Força passa a ser a de um gigante enquanto usar: de 21 (gigante da colina) até 29 (gigante das tempestades), conforme o tipo. A raridade varia de rara a lendária. Não faz nada se sua Força já for maior."},
{"id":"magico.cinto-dos-anoes","nome":"Cinto dos Anões","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Enquanto usar, você fala anão, tem vantagem pra convencer anões, ganha +2 de Constituição (máximo 20), resistência a veneno e visão no escuro. E tem 50% de chance por dia de começar a crescer uma barba cheia."},
{"id":"magico.cola-soberana","nome":"Cola Soberana","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Uma cola que gruda qualquer coisa em qualquer coisa pra sempre. Só sai com Solvente Universal, Forma Etérea ou Desejo."},
{"id":"magico.colar-da-adaptacao","nome":"Colar da Adaptação","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Você respira normalmente em qualquer ambiente (debaixo d'água, no vácuo, em gases venenosos) e tem vantagem contra envenenamento."},
{"id":"magico.colar-das-bolas-de-fogo","nome":"Colar das Bolas de Fogo","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Um colar com 4 a 9 contas. Cada uma, arremessada até 18 m, explode como uma Bola de Fogo (CD 15). Jogar várias juntas aumenta o dano."},
{"id":"magico.colar-de-contas-de-oracao","nome":"Colar de Contas de Oração","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim (só Clérigo, Druida ou Paladino)","desc":"Colar com 3 a 6 contas mágicas, pra clérigos, druidas e paladinos. Cada conta lança uma magia uma vez por dia: Bênção, Curar Ferimentos, Restauração Maior, Palavra Curativa, Arma Espiritual ou até Aliado Planar."},
{"id":"magico.conta-nutritiva","nome":"Conta Nutritiva","tipo":"Item maravilhoso","rar":"Comum","sint":"","desc":"Uma bolinha gelatinosa sem gosto que derrete na língua e alimenta tanto quanto um dia de rações."},
{"id":"magico.conta-de-energia","nome":"Conta de Energia","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Uma bolinha preta que, arremessada até 18 m, explode numa esfera de 3 m. Quem estiver lá faz teste de Destreza CD 15 ou sofre 5d4 de energia, e fica preso numa bolha de força por 1 minuto. Costuma vir em grupos de 5 a 8."},
{"id":"magico.corda-enredante","nome":"Corda Enredante","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Corda de 9 m que, sob comando, se lança e amarra uma criatura a até 6 m (teste de Destreza CD 15 ou fica contida)."},
{"id":"magico.corda-da-escalada","nome":"Corda da Escalada","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Corda mágica de 18 m que se mexe sozinha: sobe paredes, amarra e desamarra nós sob comando e aguenta 1,5 tonelada."},
{"id":"magico.cubo-de-energia","nome":"Cubo de Energia","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Um cubinho com seis faces. Apertando uma face e gastando cargas, você cria barreiras de energia ao seu redor que bloqueiam gases, criaturas, objetos ou magias, conforme a face. Tem 10 cargas e recupera 1d6 por dia."},
{"id":"magico.diadema-explosivo","nome":"Diadema Explosivo","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Uma vez por dia, lança Raio Ardente (+5 pra acertar)."},
{"id":"magico.elmo-da-telepatia","nome":"Elmo da Telepatia","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Dá telepatia a até 9 m e, uma vez por dia cada, lança Detectar Pensamentos e Sugestão (CD 13)."},
{"id":"magico.elmo-do-brilho","nome":"Elmo do Brilho","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Elmo cravejado de diamantes, rubis, opalas de fogo e opalas. Cada tipo de gema dá um poder: luz que fere mortos-vivos, Bola de Fogo, Muralha de Fogo, Luz do Dia. Também dá resistência a fogo. Quando as gemas acabam, perde a magia."},
{"id":"magico.elmo-do-teletransporte","nome":"Elmo do Teletransporte","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Tem 3 cargas pra lançar Teletransporte e recupera 1d3 por dia."},
{"id":"magico.elmo-dos-idiomas","nome":"Elmo dos Idiomas","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Enquanto usar, você pode lançar Compreender Idiomas quando quiser."},
{"id":"magico.escaravelho-da-protecao","nome":"Escaravelho da Proteção","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Medalhão que dá +1 na CA e vantagem contra magias. Com 12 cargas, transforma uma falha contra necromancia ou mortos-vivos em sucesso. Quando as cargas acabam, vira pó."},
{"id":"magico.esfera-da-aniquilacao","nome":"Esfera da Aniquilação","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Uma bola preta de 60 cm que é um buraco no universo: destrói tudo que toca, sem deixar nada. Dá pra tentar controlá-la com um teste de Arcanismo, mas perder o controle pode ser fatal."},
{"id":"magico.espelho-aprisionador","nome":"Espelho Aprisionador","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Um espelho grande que prende quem olhar nele (teste de Carisma CD 15) em uma de suas 12 celas extradimensionais. Quem está preso não envelhece nem precisa comer. Quebrar o espelho solta todo mundo."},
{"id":"magico.estatueta-do-poder-maravilhoso","nome":"Estatueta do Poder Maravilhoso","tipo":"Item maravilhoso","rar":"Varia","sint":"","desc":"Estatuetas de bolso que, arremessadas, viram criaturas de verdade que obedecem você por um tempo: corvo de prata, grifo de bronze, mosca de ébano, leões de ouro, cabras de marfim, elefante de mármore, coruja de serpentina, cão de ônix e outras. Depois voltam a ser estatueta e precisam descansar."},
{"id":"magico.faixas-de-ferro","nome":"Faixas de Ferro","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Uma esfera de ferro que, arremessada, vira faixas que prendem uma criatura (ataque à distância). Quem é preso fica contido até se libertar com um teste de Força CD 20. Funciona uma vez por dia."},
{"id":"magico.ferraduras-da-velocidade","nome":"Ferraduras da Velocidade","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Quatro ferraduras pra um cavalo. Com as quatro, ele anda 9 m a mais por turno."},
{"id":"magico.ferraduras-do-zefiro","nome":"Ferraduras do Zéfiro","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Quatro ferraduras pra um cavalo. Com elas, o animal anda no ar a poucos centímetros do chão: atravessa água, lava e terreno difícil sem deixar rastros e consegue viajar 12 horas sem cansar."},
{"id":"magico.flauta-assombrada","nome":"Flauta Assombrada","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Tem 3 cargas. Tocando, solta uma música arrepiante: quem você escolher a até 9 m faz teste de Sabedoria CD 15 ou fica amedrontado por 1 minuto."},
{"id":"magico.flauta-dos-esgotos","nome":"Flauta dos Esgotos","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Ratos comuns e gigantes não te atacam. Gastando cargas e tocando, você chama enxames de ratos que podem ficar sob seu controle se você continuar tocando."},
{"id":"magico.fortaleza-instantanea","nome":"Fortaleza Instantânea","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Uma estatueta de 2,5 cm que, com uma palavra, vira uma torre de adamante de 6 m de lado e 9 m de altura, com porta, ameias e janelas. Outra palavra faz voltar a ser estatueta, se estiver vazia."},
{"id":"magico.frasco-de-ferro","nome":"Frasco de Ferro","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Um frasco que aprisiona criaturas de outros planos (teste de Sabedoria CD 17). Depois, dá pra soltar a criatura, que te serve por 1 hora. O que já vem dentro de um frasco encontrado é surpresa."},
{"id":"magico.garrafa-da-fumaca-eterna","nome":"Garrafa da Fumaça Eterna","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Aberta, solta uma fumaça densa que bloqueia a visão numa área que cresce a cada minuto, até 36 m. Fechar faz a fumaça sumir aos poucos."},
{"id":"magico.garrafa-do-efreeti","nome":"Garrafa do Efreeti","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Abrindo a garrafa, sai um efreeti, um gênio do fogo. Na primeira vez, o mestre rola o que acontece: ele pode te atacar, servir por um tempo ou até realizar três desejos."},
{"id":"magico.gema-elemental","nome":"Gema Elemental","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Uma gema com uma faísca de um elemento (ar, terra, fogo ou água). Quebrando, invoca um elemental daquele tipo que obedece você por 1 hora. Serve uma vez."},
{"id":"magico.gema-da-visao","nome":"Gema da Visão","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Tem 3 cargas. Gastando uma, olhando através dela, você tem visão verdadeira por 10 minutos: vê o invisível, ilusões e o que está transformado."},
{"id":"magico.gema-do-brilho","nome":"Gema do Brilho","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Um prisma com 50 cargas. Com palavras de comando: brilha como uma lanterna (de graça), dispara um raio de luz que cega um alvo, ou solta um clarão em cone que pode cegar vários."},
{"id":"magico.incensario-dos-elementais-do-ar","nome":"Incensário dos Elementais do Ar","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Balançando o incensário, você invoca um elemental do ar que obedece suas ordens por 1 hora. Só funciona uma vez por dia."},
{"id":"magico.jarro-da-agua-infinita","nome":"Jarro da Água Infinita","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Um frasco que, destampado com uma palavra, jorra água doce ou salgada: um pouco, um balde ou um jato forte o bastante pra derrubar alguém. Nunca esvazia."},
{"id":"magico.lanterna-reveladora","nome":"Lanterna Reveladora","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Lanterna que, acesa, ilumina 9 m e revela tudo que está invisível dentro da luz forte."},
{"id":"magico.leque-do-vento","nome":"Leque do Vento","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Lança Lufada de Vento (CD 13). Usar mais de uma vez por dia tem 20% de chance acumulada de rasgar o leque."},
{"id":"magico.luvas-pega-projeteis","nome":"Luvas Pega-Projéteis","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Quando um ataque à distância te acertar, você usa a reação pra reduzir o dano em 1d10 + Destreza. Se zerar o dano e tiver a mão livre, pega o projétil no ar."},
{"id":"magico.luvas-de-natacao-e-escalada","nome":"Luvas de Natação e Escalada","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Dão deslocamento de escalada e de natação igual ao normal, e +5 em Atletismo pra escalar ou nadar."},
{"id":"magico.luvas-do-ladrao","nome":"Luvas do Ladrão","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Luvas invisíveis enquanto estão nas mãos. Dão +5 em Prestidigitação, ótimas pra bater carteiras e mexer em fechaduras."},
{"id":"magico.manoplas-da-forca-do-ogro","nome":"Manoplas da Força do Ogro","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Sua Força passa a ser 19 enquanto usar. Não fazem nada se a sua já for maior."},
{"id":"magico.manto-estrelado","nome":"Manto Estrelado","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Manto escuro bordado de estrelas que dá +1 nos testes de resistência. Seis estrelas grandes lançam Mísseis Mágicos de 5º círculo. Também te leva pro Plano Astral e de volta."},
{"id":"magico.manto-da-aranha","nome":"Manto da Aranha","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Manto de seda preta com fios prateados. Dá resistência a veneno, deixa andar por paredes e tetos com as mãos livres, não te deixa preso em teias e, uma vez por dia, lança Teia."},
{"id":"magico.manto-da-arraia","nome":"Manto da Arraia","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Com o capuz puxado, você respira debaixo d'água e nada a 18 m por turno."},
{"id":"magico.manto-da-invisibilidade","nome":"Manto da Invisibilidade","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Tem 3 cargas e recupera 1d3 por dia. Com uma ação, você puxa o capuz e gasta 1 carga pra ficar invisível por 1 hora, até baixar o capuz ou tirar o manto."},
{"id":"magico.manto-da-protecao","nome":"Manto da Proteção","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Dá +1 na CA e em todos os testes de resistência. Simples e muito útil."},
{"id":"magico.manto-da-resistencia-a-magia","nome":"Manto da Resistência à Magia","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Dá vantagem em testes de resistência contra magias."},
{"id":"magico.manto-das-cores-cintilantes","nome":"Manto das Cores Cintilantes","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Tem 3 cargas. Gastando uma, o manto brilha em cores hipnóticas até seu próximo turno: ilumina 9 m, quem te olha pode ficar atordoado e todos têm desvantagem pra te atacar."},
{"id":"magico.manto-do-arquimago","nome":"Manto do Arquimago","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim (só Feiticeiro, Bruxo ou Mago)","desc":"Lendário, pra feiticeiros, bruxos e magos. Sem armadura, sua CA base vira 15 + Destreza, você tem vantagem contra magias e a CD das suas magias e o bônus de ataque mágico aumentam em 2."},
{"id":"magico.manto-do-deslocamento","nome":"Manto do Deslocamento","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Uma ilusão faz você parecer estar um pouco ao lado de onde está: todos têm desvantagem pra te atacar. Se você levar dano, o efeito para até o começo do seu próximo turno."},
{"id":"magico.manto-do-morcego","nome":"Manto do Morcego","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Dá vantagem em Furtividade. No escuro ou na penumbra, segurando as pontas, você voa a 12 m por turno. Uma vez por dia, também pode virar um morcego, como em Metamorfose."},
{"id":"magico.manto-dos-itens-uteis","nome":"Manto dos Itens Úteis","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Coberto de remendos. Cada remendo, arrancado, vira o objeto que mostra: adaga, lanterna, espelho, vara, corda, saco. Vários remendos aleatórios trazem coisas maiores, como escada, barco, poço ou até um baú de ouro."},
{"id":"magico.manto-dos-olhos","nome":"Manto dos Olhos","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Coberto de desenhos de olhos. Dá vantagem em Percepção, visão no escuro e visão verdadeira até 36 m. Mas uma magia Luz lançada nele te cega por 1 minuto."},
{"id":"magico.manto-elfico","nome":"Manto Élfico","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Com o capuz puxado, quem tenta te perceber tem desvantagem, e você tem vantagem em Furtividade. A cor do manto muda pra combinar com o ambiente."},
{"id":"magico.manual-da-agilidade","nome":"Manual da Agilidade","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Um livro de equilíbrio e coordenação. Estudando 48 horas em 6 dias, sua Destreza aumenta em 2 (máximo 30). Depois o livro perde a magia por um século."},
{"id":"magico.manual-da-saude-corporal","nome":"Manual da Saúde Corporal","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Um livro de exercícios e alimentação. Estudando 48 horas em 6 dias, sua Constituição aumenta em 2 (máximo 30). Depois o livro perde a magia por um século."},
{"id":"magico.manual-do-bom-exercicio","nome":"Manual do Bom Exercício","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Um livro de treinos. Estudando 48 horas em 6 dias, sua Força aumenta em 2 (máximo 30). Depois o livro perde a magia por um século."},
{"id":"magico.manual-dos-golens","nome":"Manual dos Golens","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Livro com as instruções pra construir um tipo de golem (barro, carne, ferro ou pedra). Exige um conjurador poderoso, muito ouro e semanas de trabalho, mas no fim você tem um golem leal."},
{"id":"magico.medalhao-dos-pensamentos","nome":"Medalhão dos Pensamentos","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Tem 5 cargas pra lançar Detectar Pensamentos (CD 13) e recupera 1d4 por dia."},
{"id":"magico.mochila-pratica","nome":"Mochila Prática","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Mochila com três bolsos extradimensionais: dois laterais de 100 kg e um central de 250 kg. Sempre pesa 2,5 kg, e o que você procurar sempre está no topo, então pegar algo é rápido."},
{"id":"magico.olhos-encantadores","nome":"Olhos Encantadores","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Lentes de cristal com 3 cargas pra lançar Enfeitiçar Pessoa (CD 13). Gastar mais cargas lança a magia num círculo maior. Recuperam as cargas todo dia."},
{"id":"magico.olhos-da-visao-minuciosa","nome":"Olhos da Visão Minuciosa","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Lentes que dão visão perfeita bem de perto (30 cm): visão no escuro e vantagem pra examinar detalhes, como fechaduras e documentos."},
{"id":"magico.olhos-de-aguia","nome":"Olhos de Águia","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Lentes que dão vantagem em Percepção pela visão e deixam você enxergar detalhes de coisas pequenas a distâncias enormes."},
{"id":"magico.orbe-do-dragao","nome":"Orbe do Dragão","tipo":"Item maravilhoso","rar":"Artefato","sint":"Sim","desc":"Um artefato lendário: um globo de cristal que guarda a essência de um dragão. Quem domina o orbe pode chamar e controlar dragões, lançar magias poderosas e enxergar longe, mas olhar dentro dele exige um teste de Carisma, e falhar pode deixar você sob o controle do próprio orbe."},
{"id":"magico.pedra-ioun","nome":"Pedra Ioun","tipo":"Item maravilhoso","rar":"Varia","sint":"Sim","desc":"Pedrinhas que orbitam sua cabeça e dão um benefício, conforme o tipo: +1 na CA, +2 em um atributo, regenerar PV, absorver magias, não precisar comer nem respirar, ver no escuro e outros. Pegar uma no ar exige um ataque."},
{"id":"magico.pedra-da-sorte","nome":"Pedra da Sorte","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Uma ágata polida que dá +1 em todos os testes de atributo e de resistência."},
{"id":"magico.pedra-dos-elementais-da-terra","nome":"Pedra dos Elementais da Terra","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Encostada no chão, invoca um elemental da terra que obedece você por 1 hora. Uma vez por dia."},
{"id":"magico.pedras-de-comunicacao","nome":"Pedras de Comunicação","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Um par de pedras gêmeas. Uma vez por dia, quem segura uma pode lançar Enviar Mensagem pra quem estiver com a outra, a qualquer distância."},
{"id":"magico.pena-magica","nome":"Pena Mágica","tipo":"Item maravilhoso","rar":"Varia","sint":"","desc":"Uma pena com um efeito de uso único, que varia: âncora (prende um barco), pássaro (vira uma ave gigante que leva você), leque (cria vento pra um barco), barco de cisne, árvore (vira uma árvore de verdade) ou chicote (um chicote voador que ataca)."},
{"id":"magico.pigmentos-maravilhosos","nome":"Pigmentos Maravilhosos","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Potes de tinta mágica: o que você pintar vira real. Uma porta pintada vira uma porta, uma ponte vira uma ponte. Não cria criaturas nem objetos de valor como ouro e joias."},
{"id":"magico.pingente-contra-veneno","nome":"Pingente Contra Veneno","tipo":"Item maravilhoso","rar":"Raro","sint":"Sim","desc":"Corrente de prata com uma gema negra. Dá imunidade a dano de veneno e a ficar envenenado."},
{"id":"magico.pingente-da-saude","nome":"Pingente da Saúde","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Uma vez por dia, com uma ação, recupera 2d4 + 2 PV. Também dá vantagem contra envenenamento."},
{"id":"magico.pingente-do-fechamento-de-feridas","nome":"Pingente do Fechamento de Feridas","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Nos testes contra a morte, um resultado de 9 ou menos vira 10. E sempre que você rola dados de vida pra se curar, recupera o dobro."},
{"id":"magico.portal-cubico","nome":"Portal Cúbico","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Um cubo cujas seis faces são ligadas a planos diferentes. Gastando cargas, você abre um portal pra um desses planos ou manda alguém pra lá (com teste de Carisma). Tem 3 cargas e recupera 1d3 por dia."},
{"id":"magico.poco-dos-muitos-mundos","nome":"Poço dos Muitos Mundos","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Um pano preto que, aberto, vira um portal de mão dupla pra um plano aleatório. Fica aberto até ser dobrado de novo."},
{"id":"magico.perola-do-poder","nome":"Pérola do Poder","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim (só conjurador)","desc":"Uma vez por dia, com uma ação, recupera um espaço de magia gasto de 3º círculo ou menos. Só pra conjuradores."},
{"id":"magico.po-da-secura","nome":"Pó da Secura","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Pitadas de pó (5 a 10) que transformam até um cubo de 4,5 m de água numa bolinha do tamanho de uma bola de gude. Quebrando a bolinha, a água volta toda. Contra elementais da água e criaturas feitas de água, causa dano."},
{"id":"magico.po-do-desaparecimento","nome":"Pó do Desaparecimento","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Jogado pro alto, deixa você e todos a até 3 m invisíveis por 2d4 minutos. A invisibilidade de cada um acaba se ele atacar ou conjurar. Serve uma vez."},
{"id":"magico.po-do-espirro-e-engasgo","nome":"Pó do Espirro e Engasgo","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Parece Pó do Desaparecimento, até mesmo pra Identificação. Mas, jogado pro alto, faz você e todos a até 9 m fazerem teste de Constituição: quem falha fica incapacitado, espirrando e engasgando sem parar."},
{"id":"magico.saco-devorador","nome":"Saco Devorador","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Parece uma Bolsa Guarda-Tudo, mas é a boca de uma criatura de outra dimensão. Tudo que for orgânico colocado dentro é devorado e some pra sempre, e quem enfiar o braço pode ser puxado pra dentro."},
{"id":"magico.saco-de-feijoes","nome":"Saco de Feijões","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Um saco com 3d4 feijões mágicos. Despejados no chão, explodem e causam dano de fogo em volta. Plantados e regados, cada um faz brotar algo imprevisível: de uma árvore com frutas que curam a um bando de criaturas, um tesouro ou até uma criatura hostil. O mestre rola o resultado."},
{"id":"magico.saco-de-truques","nome":"Saco de Truques","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Um saco que parece vazio, mas tem um bichinho peludo dentro. Com uma ação você puxa e arremessa a bolinha, que vira um animal aleatório (rato, lobo, urso, javali, conforme a cor do saco) que obedece você por 1 hora. Funciona três vezes por dia."},
{"id":"magico.sapatilhas-da-aranha","nome":"Sapatilhas da Aranha","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Você anda por paredes e tetos com as mãos livres, menos em superfícies escorregadias."},
{"id":"magico.sino-da-abertura","nome":"Sino da Abertura","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Um tubo de metal que, tocado, lança Arrombar com um som de sino que dá pra ouvir a 90 m. Funciona 10 vezes e depois racha."},
{"id":"magico.solvente-universal","nome":"Solvente Universal","tipo":"Item maravilhoso","rar":"Lendário","sint":"","desc":"Um líquido com cheiro de álcool que dissolve qualquer cola ou adesivo, até a Cola Soberana."},
{"id":"magico.talisma-da-esfera","nome":"Talismã da Esfera","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Dá vantagem pra controlar uma Esfera da Aniquilação e deixa movê-la mais longe."},
{"id":"magico.talisma-do-bem-puro","nome":"Talismã do Bem Puro","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim (só Clérigo ou Paladino)","desc":"Símbolo sagrado lendário. Demônios e mortos-vivos que o tocam sofrem 8d6 radiante. Dá +2 nos ataques mágicos e pode abrir uma fenda flamejante que engole uma criatura maligna."},
{"id":"magico.talisma-do-mal-supremo","nome":"Talismã do Mal Supremo","tipo":"Item maravilhoso","rar":"Lendário","sint":"Sim","desc":"Símbolo profano lendário. Quem não é demônio nem morto-vivo e o toca sofre 8d6 necrótico. Dá +2 nos ataques mágicos e pode abrir uma fenda que engole uma criatura bondosa."},
{"id":"magico.tapete-voador","nome":"Tapete Voador","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Um tapete que voa sob comando, levando pessoas e carga. Existem quatro tamanhos, do pequeno (uma pessoa, rápido) ao grande (várias pessoas, mais lento). Fica mais lento se carregar mais do que o peso indicado."},
{"id":"magico.tiara-do-intelecto","nome":"Tiara do Intelecto","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Sua Inteligência passa a ser 19 enquanto usar. Não faz nada se a sua já for maior."},
{"id":"magico.tigela-dos-elementais-da-agua","nome":"Tigela dos Elementais da Água","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Com a tigela cheia de água, você invoca um elemental da água que obedece suas ordens por 1 hora. Só funciona uma vez por dia."},
{"id":"magico.tomo-da-lideranca-e-influencia","nome":"Tomo da Liderança e Influência","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Livro sobre como influenciar pessoas. Estudando 48 horas em 6 dias, seu Carisma aumenta em 2 (máximo 30). Depois perde a magia por um século."},
{"id":"magico.tomo-do-entendimento","nome":"Tomo do Entendimento","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Livro de intuição e percepção. Estudando 48 horas em 6 dias, sua Sabedoria aumenta em 2 (máximo 30). Depois perde a magia por um século."},
{"id":"magico.tomo-do-pensamento-claro","nome":"Tomo do Pensamento Claro","tipo":"Item maravilhoso","rar":"Muito raro","sint":"","desc":"Livro de exercícios de lógica e memória. Estudando 48 horas em 6 dias, sua Inteligência aumenta em 2 (máximo 30). Depois perde a magia por um século."},
{"id":"magico.trompa-da-destruicao","nome":"Trompa da Destruição","tipo":"Item maravilhoso","rar":"Raro","sint":"","desc":"Soprada, solta um estrondo num cone de 9 m: teste de Constituição CD 15, 5d8 de trovão e surdez por 1 minuto. Destrói vidro e cristal. Cada uso tem 20% de chance de explodir na sua cara."},
{"id":"magico.trompa-de-valhalla","nome":"Trompa de Valhalla","tipo":"Item maravilhoso","rar":"Varia","sint":"","desc":"Soprada, invoca espíritos de guerreiros berserkers que lutam por você por 1 hora. Quanto mais nobre o metal (prata, latão, bronze, ferro), mais guerreiros vêm. Funciona uma vez por semana."},
{"id":"magico.vassoura-voadora","nome":"Vassoura Voadora","tipo":"Item maravilhoso","rar":"Incomum","sint":"Sim","desc":"Funciona como vassoura comum até você montar nela: voa a 15 m por turno carregando até 200 kg (mais devagar se passar de 100 kg). Também dá pra mandar ela voar sozinha até um lugar a até 1,5 km e voltar quando chamar."},
{"id":"magico.vela-da-invocacao","nome":"Vela da Invocação","tipo":"Item maravilhoso","rar":"Muito raro","sint":"Sim","desc":"Vela ligada a um deus ou tendência. Acesa, ilumina 9 m: seguidores dessa crença ali têm vantagem em ataques, testes e resistências, e clérigos e druidas dela conjuram magias de 1º círculo sem gastar espaço. Dura 4 horas no total. Também dá pra gastar a vela toda pra lançar Portal."},
{"id":"magico.oculos-da-noite","nome":"Óculos da Noite","tipo":"Item maravilhoso","rar":"Incomum","sint":"","desc":"Lentes escuras que dão visão no escuro até 18 m, ou aumentam em 18 m a que você já tem."}];